// ---------- static-data figures: bars, chart, grid, timeline ----------
const FCOL = {c1: 'var(--c1)', c2: 'var(--c2)', c3: 'var(--c3)', c4: 'var(--c4)', go: 'var(--wine)', wine: 'var(--wine)', flame: 'var(--flame)', gold: 'var(--gold)', line: 'var(--line2)', kraft: 'var(--kraft)'};
const FCYC = ['c1', 'c3', 'c2', 'go', 'flame', 'c4'];
function fOpts(lines){ const o = {}, rest = []; lines.forEach(l => { const m = l.match(/^(\w+)\s*=\s*(.+)$/); if (m && !l.includes('|')) o[m[1]] = m[2].trim(); else rest.push(l); }); return [o, rest]; }
function fWrap(kind, inner, cap){ return `<figure class="dg fig fig-${kind}">${inner}${cap ? `<figcaption>${inl(cap)}</figcaption>` : ''}</figure>`; }
const FIG = {};
FIG.bars = (cap, lines) => {
  const [o, rows] = fOpts(lines), stk = o.stack ? o.stack.split(/\s*,\s*/) : null, u = o.unit ? ' ' + o.unit : '';
  const R = rows.map(l => { const p = l.split(/\s*\|\s*/); const vs = p[1].split('+').map(Number); return {l: p[0], vs, t: vs.reduce((a, b) => a + b, 0), c: p[2] || '', n: p[3] || ''}; });
  const mx = Math.max(...R.map(r => r.t)) || 1;
  const bar = r => `<div class="wtr" title="${esc(r.l)}: ${fmtN(r.t)}${u}${r.n ? ' (' + esc(r.n) + ')' : ''}"><span>${inl(r.l)}</span><div>${r.vs.map((v, k) => `<i style="width:${v / mx * 100}%;background:${FCOL[stk ? FCYC[k] : (r.c || 'c3')] || r.c}" title="${stk ? esc(stk[k]) + ': ' : ''}${fmtN(v)}${u}"></i>`).join('')}</div><b>${fmtN(r.t)}${u}</b></div>${r.n ? `<p class="wnote fnote">${inl(r.n)}</p>` : ''}`;
  return fWrap('bars', `<div class="wtp wide">${R.map(bar).join('')}</div>${stk ? `<div class="wleg">${stk.map((s, k) => `<span><i style="background:${FCOL[FCYC[k]]}"></i>${esc(s)}</span>`).join('')}</div>` : ''}`, cap);
};
FIG.chart = (cap, lines) => {
  const [o, rows] = fOpts(lines), xs = o.x.split(/\s*,\s*/).map(Number);
  const series = rows.map((l, k) => { const i = l.indexOf(':'); const name = l.slice(0, i).trim(); const dash = name.endsWith('*'); return {name: name.replace(/\*$/, ''), dash, c: FCOL[FCYC[k % FCYC.length]], ys: l.slice(i + 1).split(/\s*,\s*/).map(v => v === '' || v === '-' ? NaN : Number(v))}; });
  const marks = o.mark ? [{x: +o.mark, t: o.markt || ''}] : [];
  return fWrap('chart', lineChart({xs, series, xlab: o.xlab || '', ylab: o.ylab || '', logx: o.logx == 1, logy: o.logy == 1, ymin: o.ymin != null ? +o.ymin : undefined, ymax: o.ymax != null ? +o.ymax : undefined, marks, tfmt: o.unit ? (v => fmtN(v) + ' ' + o.unit) : undefined}), cap);
};
FIG.grid = (cap, lines) => {
  const [o, rows0] = fOpts(lines), keys = {}, rows = [];
  rows0.forEach(l => { const m = l.match(/^key\s+(\S)\s*=\s*([^|]+?)\s*(?:\|\s*(\S+))?$/); if (m) keys[m[1]] = {t: m[2], c: FCOL[m[3]] || m[3] || 'var(--c3)'}; else rows.push(l); });
  const heat = o.heat == 1, cols = o.cols ? o.cols.split(/\s*,\s*/) : null;
  const data = rows.map(l => { const p = l.split(/\s*\|\s*/); return p.length > 1 ? {lab: p[0], cells: p[1].split(/\s+/)} : {lab: '', cells: p[0].split(/\s+/)}; });
  const nums = heat ? data.flatMap(r => r.cells.map(Number).filter(isFinite)) : [], hmx = Math.max(...nums, 1), hmn = Math.min(...nums, 0);
  const n = Math.max(...data.map(r => r.cells.length)), cw = Math.max(16, Math.min(40, Math.floor(520 / n))), lw = data.some(r => r.lab) ? Math.min(150, 8 + 7 * Math.max(...data.map(r => r.lab.length))) : 0, top = cols ? 22 : 4;
  let s = '';
  if (cols) cols.forEach((c, j) => s += `<text x="${lw + j * cw + cw / 2}" y="14" text-anchor="middle" class="tk">${esc(c)}</text>`);
  data.forEach((r, i) => { if (r.lab) s += `<text x="${lw - 6}" y="${top + i * cw + cw / 2 + 4}" text-anchor="end" class="tk">${esc(r.lab)}</text>`;
    r.cells.forEach((c, j) => { const x = lw + j * cw, y = top + i * cw; if (c === '.' || c === '_'){ s += `<rect x="${x + 1}" y="${y + 1}" width="${cw - 2}" height="${cw - 2}" rx="3" fill="none" stroke="var(--line)"/>`; return; }
      if (heat){ const v = +c, f = (v - hmn) / (hmx - hmn || 1); s += `<g><title>${esc(r.lab)} ${cols ? esc(cols[j]) : ''}: ${c}</title><rect x="${x + 1}" y="${y + 1}" width="${cw - 2}" height="${cw - 2}" rx="3" fill="color-mix(in oklab, var(--c1) ${Math.round(8 + f * 92)}%, var(--card))"/>${cw >= 26 ? `<text x="${x + cw / 2}" y="${y + cw / 2 + 4}" text-anchor="middle" class="tk b" style="fill:${f > .55 ? '#fff' : 'var(--ink)'}">${c}</text>` : ''}</g>`; return; }
      const k = keys[c[0]] || {t: c, c: 'var(--c4)'}, lab = c.length > 1 ? c.slice(1) : '';
      s += `<g><title>${esc(k.t)}${lab ? ' ' + esc(lab) : ''}</title><rect x="${x + 1}" y="${y + 1}" width="${cw - 2}" height="${cw - 2}" rx="3" fill="${k.c}"/>${lab && cw >= 22 ? `<text x="${x + cw / 2}" y="${y + cw / 2 + 4}" text-anchor="middle" class="tk b" style="fill:#fff">${esc(lab)}</text>` : ''}</g>`; }); });
  const W = lw + n * cw + 4, H = top + data.length * cw + 4;
  const leg = Object.keys(keys).length ? `<div class="wleg">${Object.values(keys).map(k => `<span><i style="background:${k.c}"></i>${esc(k.t)}</span>`).join('')}</div>` : '';
  return fWrap('grid', `<div class="dg-scroll wchart"><svg viewBox="0 0 ${W} ${H}" style="width:100%;max-width:${W}px;height:auto">${s}</svg></div>${leg}`, cap);
};
FIG.timeline = (cap, lines) => {
  const [o, rows] = fOpts(lines), u = o.unit || '';
  const L = rows.map(l => { const [lab, sp] = l.split(/\s*\|\s*/); return {lab, spans: (sp || '').split(/\s*;\s*/).filter(Boolean).map(x => { const m = x.match(/^([\d.]+)\s*-\s*([\d.]+)\s*(.*?)\s*(c1|c2|c3|c4|go|wine|flame|gold|line|kraft)?$/); return m ? {a: +m[1], b: +m[2], t: m[3], c: FCOL[m[4] || 'c3']} : null; }).filter(Boolean)}; });
  const T = o.end ? +o.end : Math.max(...L.flatMap(r => r.spans.map(s => s.b))), lw = Math.min(140, 10 + 7 * Math.max(...L.map(r => r.lab.length))), W = 600, iw = W - lw - 10, rh = 30, X = t => lw + t / T * iw;
  let s = '';
  const st = +(o.tick || niceStep(T / 6));
  for (let t = 0; t <= T + 1e-9; t += st) s += `<line x1="${X(t)}" x2="${X(t)}" y1="0" y2="${L.length * rh}" class="gl v"/><text x="${X(t)}" y="${L.length * rh + 14}" text-anchor="middle" class="tk">${fmtN(+t.toFixed(6))}${u && t === 0 ? '' : ''}</text>`;
  L.forEach((r, i) => { s += `<text x="${lw - 8}" y="${i * rh + 19}" text-anchor="end" class="tk">${esc(r.lab)}</text>`;
    r.spans.forEach(p => { const w = X(p.b) - X(p.a), dark = /c1|c3|kraft|go|wine/.test(p.c); s += `<g class="tsp"><title>${esc(r.lab)}: ${esc(p.t)} (${fmtN(p.a)} to ${fmtN(p.b)}${u ? ' ' + u : ''})</title><rect x="${X(p.a) + .5}" y="${i * rh + 4}" width="${Math.max(1, w - 1)}" height="${rh - 8}" rx="4" fill="${p.c}"/>${w > 7 * p.t.length + 6 ? `<text x="${X(p.a) + w / 2}" y="${i * rh + 19}" text-anchor="middle" class="tk b" style="fill:var(--on-${(p.c.match(/--([a-z0-9]+)/) || [0, 'c3'])[1]})">${esc(p.t)}</text>` : ''}</g>`; }); });
  const H = L.length * rh + 34;
  s += `<text x="${lw + iw / 2}" y="${H - 2}" text-anchor="middle" class="ax">${esc(o.xlab || (u ? 'Time (' + u + ')' : 'Time'))}</text>`;
  return fWrap('timeline', `<div class="dg-scroll wchart"><svg viewBox="0 0 ${W} ${H}" style="width:100%;max-width:${W}px;height:auto">${s}</svg></div>`, cap);
};

